from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework_simplejwt.token_blacklist.models import BlacklistedToken, OutstandingToken

class CheckTokenRevocationStatusView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        jti = request.query_params.get("jti")
        if not jti:
            return Response({"error": "jti parameter required"}, status=400)

        token = OutstandingToken.objects.filter(jti=jti, user=request.user).first()
        if not token and not request.user.is_staff:
            return Response({"detail": "Token not found or unauthorized"}, status=404)

        is_blacklisted = BlacklistedToken.objects.filter(token=token).exists()
        return Response({
            "jti": jti,
            "is_blacklisted": is_blacklisted,
            "created_at": token.created_at,
            "expires_at": token.expires_at
        })
